        "detailContent": "<h3>🌿 Lán Nà Nưa — Trái tim phát lệnh Tổng khởi nghĩa</h3><p>Sau khi Nhật đảo chính Pháp (9/3/1945), Đảng ta kịp thời phát động <em>Cao trào kháng Nhật cứu nước</em>. Suốt 5 tháng ròng (từ tháng 3 đến tháng 8/1945), các chiến khu giải phóng được mở rộng, quần chúng nhân dân được tập dượt qua các cuộc đấu tranh vũ trang và biểu tình phá kho thóc Nhật cứu đói.</p><p>Tại Lán Nà Nưa (Tân Trào, Tuyên Quang), dù đang cơn sốt rét rừng hiểm nghèo, Chủ tịch Hồ Chí Minh đã căn dặn đồng chí Võ Nguyên Giáp câu nói bất hủ: <i>'Lúc này thời cơ đã đến, dù hy sinh tới đâu, dù phải đốt cháy cả dãy Trường Sơn cũng phải kiên quyết giành cho được độc lập!'</i>. Đêm <strong>13/8/1945</strong>, Ủy ban Khởi nghĩa toàn quốc ra đời và ban bố <strong>Quân lệnh số 1</strong>, thổi bùng ngọn lửa Tổng khởi nghĩa trên toàn dải đất hình chữ S.</p>",
