        "detailContent": "<h3>👑 Chiều Ba Mươi tháng Tám — Hồi chuông cáo chung của chế độ phong kiến</h3><p>Chiều ngày <strong>30/8/1945</strong>, tại Quảng trường trước Ngọ Môn (Cố đô Huế), một sự kiện có một không hai trong lịch sử dân tộc diễn ra trước sự chứng kiến của hơn 5 vạn đồng bào. Vua Bảo Đại – vị hoàng đế thứ 13 và cũng là cuối cùng của triều Nguyễn – mặc hoàng bào vàng trang nghiêm đọc bản <em>Chiếu thoái vị</em>.</p><p>Vua Bảo Đại tự tay trao chiếc <strong>Quốc ấn bằng vàng</strong> nặng gần 10 kg và thanh <strong>Bảo kiếm nạm ngọc</strong> cho đồng chí Trần Huy Liệu và Cù Huy Cận – đại diện Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa. Vị cựu hoàng xúc động cất lên câu nói lưu truyền sử sách: <i>'Trẫm muốn làm dân một nước tự do, hơn làm vua một nước nô lệ'</i>. Lá cờ vàng ba que của triều đình bị hạ xuống, lá cờ đỏ sao vàng kiêu hãnh bay lên đỉnh Kỳ đài trong tiếng reo hò sấm dậy của muôn người. Hơn 1.000 năm chế độ quân chủ phong kiến Việt Nam chính thức cáo chung!</p>",
